const body = $json.body || {};
const errors = [];

const messageId = String(body.message_id ?? '').trim();
const email = String(body.sender_email ?? '').trim().toLowerCase();
const subject = String(body.subject ?? '').trim();
const messageBody = String(body.message_body ?? '').trim();
const channel = String(body.channel ?? 'email').trim().toLowerCase();

if (!messageId) errors.push('message_id is required');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errors.push('sender_email is missing or invalid');
if (messageBody.length < 5) errors.push('message_body must be at least 5 characters');
if (messageBody.length > 5000) errors.push('message_body exceeds 5000 characters');
if (subject.length > 200) errors.push('subject exceeds 200 characters');
if (!['email', 'web', 'chat'].includes(channel)) errors.push('channel must be email, web, or chat');

return {
  json: {
    valid: errors.length === 0,
    errors,
    message: {
      message_id: messageId,
      sender_email: email,
      subject,
      message_body: messageBody,
      channel
    }
  }
};

