const REQUEST_TYPES = [
  'Technical Support', 'Adoption Question', 'How-To / Product Guidance',
  'Billing / Administrative', 'Feature Request', 'Account / Access',
  'Strategic Adoption Blocker', 'Commercial Opportunity', 'General Question'
];
const SENTIMENTS = ['positive', 'neutral', 'negative', 'very_negative'];

const base = $('Build Context').item.json;
const raw = String($json.text ?? '').replace(/```json|```/g, '').trim();

const fallback = {
  request_type: 'General Question',
  summary: 'AI classification failed; human review required.',
  sentiment: 'neutral',
  confidence: 0,
  adoption_blocker: false,
  risk_signals: [],
  commercial_signal: false,
  needs_knowledge_retrieval: false,
  topic_key: null
};

let ai;
let error = null;
try {
  const p = JSON.parse(raw);
  const conf = Number(p.confidence);
  if (!REQUEST_TYPES.includes(p.request_type)) throw new Error('invalid request_type');
  if (!SENTIMENTS.includes(p.sentiment)) throw new Error('invalid sentiment');
  if (!Number.isFinite(conf) || conf < 0 || conf > 1) throw new Error('invalid confidence');
  ai = {
    request_type: p.request_type,
    summary: String(p.summary ?? '').slice(0, 500),
    sentiment: p.sentiment,
    confidence: conf,
    adoption_blocker: p.adoption_blocker === true,
    risk_signals: Array.isArray(p.risk_signals) ? p.risk_signals.map(String).slice(0, 5) : [],
    commercial_signal: p.commercial_signal === true,
    needs_knowledge_retrieval: p.needs_knowledge_retrieval === true,
    topic_key: p.topic_key
      ? String(p.topic_key).toLowerCase().replace(/[^a-z0-9_]/g, '_').slice(0, 60)
      : null
  };
} catch (e) {
  error = e.message;
  ai = fallback;
}

return { json: { ...base, ai, ai_failed: error !== null, ai_error: error } };

const base = $('Parse AI Output').item.json;
let status = 'skipped';
let docs = [];

if ($json.rag_status) {
  status = $json.rag_status;      // 'ok' or 'no_match'
  docs = $json.docs || [];
} else if ($json.error) {
  status = 'failed';              // RAG sub-workflow errored
}

return {
  json: { ...base, knowledge: { status, docs, doc_ids: docs.map(d => d.doc_id) } }
};

const ACTIONS = ['draft_response', 'notify_csm', 'create_followup_task',
                 'escalate', 'route_billing', 'human_review'];

const base = $('Attach Knowledge').item.json;
const raw = String($json.output ?? '').replace(/```json|```/g, '').trim();
const steps = Array.isArray($json.intermediateSteps) ? $json.intermediateSteps : [];
const toolsCalled = steps.map(s => s?.action?.tool).filter(Boolean);

const fallback = {
  analysis: 'Agent analysis failed; human review required.',
  knowledge_sufficient: false,
  adoption_blocker: false,
  blocker_description: null,
  risk_signals: [],
  commercial_signal: false,
  recommended_actions: ['human_review'],
  evidence: [],
  confidence: 0
};

let agent;
let error = null;
try {
  const p = JSON.parse(raw);
  const conf = Number(p.confidence);
  if (typeof p.analysis !== 'string' || !p.analysis) throw new Error('missing analysis');
  if (!Number.isFinite(conf) || conf < 0 || conf > 1) throw new Error('invalid confidence');
  const actions = Array.isArray(p.recommended_actions)
    ? p.recommended_actions.filter(a => ACTIONS.includes(a)) : [];
  agent = {
    analysis: p.analysis.slice(0, 800),
    knowledge_sufficient: p.knowledge_sufficient === true,
    adoption_blocker: p.adoption_blocker === true,
    blocker_description: p.blocker_description ? String(p.blocker_description).slice(0, 300) : null,
    risk_signals: Array.isArray(p.risk_signals) ? p.risk_signals.map(String).slice(0, 5) : [],
    commercial_signal: p.commercial_signal === true,
    recommended_actions: actions.length ? actions : ['human_review'],
    evidence: Array.isArray(p.evidence) ? p.evidence.map(String).slice(0, 5) : [],
    confidence: conf
  };
} catch (e) {
  error = e.message;
  agent = fallback;
}

return {
  json: { ...base, agent, agent_failed: error !== null, agent_error: error, tools_called: toolsCalled }
};

const RANK = { healthy: 0, watch: 1, at_risk: 2, high_risk: 3 };
const STATUS = ['healthy', 'watch', 'at_risk', 'high_risk'];

const d = $json;
const c = d.customer;
const ctx = d.context;
const text = `${d.message.subject} ${d.message.message_body}`;

// ---------- Signals ----------
const negative = ['negative', 'very_negative'].includes(d.ai.sentiment);
const veryNegative = d.ai.sentiment === 'very_negative';
const adoptionBlocker = d.ai.adoption_blocker === true || d.agent.adoption_blocker === true;
const lowAdoption = c.adoption_score < 40;
const multipleUnresolved = ctx.unresolved_count >= 3;
const cancelLanguage = /\b(cancel|cancelling|canceling|switch(ing)? to|other options|alternatives?|competitors?|not renew|leaving)\b/i.test(text);

const daysToRenewal = c.renewal_date
  ? Math.ceil((new Date(c.renewal_date) - new Date()) / 86400000)
  : null;
const renewalSoon = daysToRenewal !== null && daysToRenewal >= 0 && daysToRenewal <= 90;

const h = ctx.recent_health || [];   // newest first
let decliningHealth = false;
if (h.length >= 2) {
  const newest = h[0];
  const oldest = h[h.length - 1];
  const drop = (newest.adoption_score != null && oldest.adoption_score != null)
    ? newest.adoption_score - oldest.adoption_score : 0;
  decliningHealth = RANK[newest.health_status] > RANK[oldest.health_status] || drop <= -10;
}

// ---------- Rules ----------
const rules = [];
const fire = (id, status, reason) => rules.push({ id, status, reason });

if (veryNegative && decliningHealth)
  fire('R1_VERY_NEGATIVE_DECLINING', 'high_risk', 'Very negative sentiment with declining health history');
if (cancelLanguage && renewalSoon)
  fire('R2_CANCEL_NEAR_RENEWAL', 'high_risk', 'Cancellation language within 90 days of renewal');
else if (cancelLanguage)
  fire('R2_CANCEL_LANGUAGE', 'at_risk', 'Message contains cancellation or switching language');
if (negative && adoptionBlocker)
  fire('R3_NEGATIVE_BLOCKER', 'at_risk', 'Negative sentiment with an adoption blocker');
if (multipleUnresolved && negative)
  fire('R4_UNRESOLVED_NEGATIVE', 'at_risk', '3 or more unresolved interactions with negative sentiment');
if (lowAdoption && renewalSoon)
  fire('R5_LOW_ADOPTION_RENEWAL', 'at_risk', 'Adoption score below 40 with renewal within 90 days');
if (lowAdoption)
  fire('R6_LOW_ADOPTION', 'watch', 'Adoption score below 40');
if (adoptionBlocker)
  fire('R7_ADOPTION_BLOCKER', 'watch', 'Possible adoption blocker identified');

// ---------- Result ----------
const derivedRank = Math.max(0, ...rules.map(r => RANK[r.status]));
const computedRank = Math.max(RANK[c.health_status] ?? 0, derivedRank);
const computedStatus = STATUS[computedRank];

const escalationReasons = [];
if (multipleUnresolved) escalationReasons.push('3 or more unresolved interactions');
if (cancelLanguage) escalationReasons.push('Cancellation or switching language');
if (computedStatus === 'high_risk') escalationReasons.push('Computed health is high_risk');

return {
  json: {
    ...d,
    health: {
      previous_status: c.health_status,
      computed_status: computedStatus,
      status_changed: computedStatus !== c.health_status,
      escalation_candidate: escalationReasons.length > 0,
      escalation_reasons: escalationReasons,
      rules_triggered: rules.map(r => r.id),
      reasons: rules.map(r => r.reason),
      signals: {
        negative, very_negative: veryNegative, adoption_blocker: adoptionBlocker,
        low_adoption: lowAdoption, multiple_unresolved: multipleUnresolved,
        cancel_language: cancelLanguage, renewal_soon: renewalSoon,
        days_to_renewal: daysToRenewal, declining_health: decliningHealth
      },
      signals_degraded: d.ai_failed === true || d.agent_failed === true
    }
  }
};

const MIN_CONFIDENCE = 0.7;   // below this: a human handles it, no AI draft
const AUTO_CONFIDENCE = 0.8;  // at or above this (and low risk): auto response allowed

const d = $json;
const c = d.customer;
const text = `${d.message.subject} ${d.message.message_body}`;
const confidence = Math.min(d.ai.confidence, d.agent.confidence);

const rules = [];
const reasons = [];
const hit = (id, why) => { rules.push(id); reasons.push(why); };

// ---------- Flags ----------
const degraded = d.health.signals_degraded === true;
const lowConfidence = confidence < MIN_CONFIDENCE;
const knowledgeGap = d.ai.needs_knowledge_retrieval && !d.agent.knowledge_sufficient;
const securityConcern = /\b(security|breach|data leak|data loss|hacked|unauthori[sz]ed)\b/i.test(text);
const isBilling = d.ai.request_type === 'Billing / Administrative';
const commercial = !degraded && (d.ai.request_type === 'Commercial Opportunity'
  || d.ai.commercial_signal === true || d.agent.commercial_signal === true);
const blocker = !degraded && (d.health.signals.adoption_blocker
  || d.ai.request_type === 'Strategic Adoption Blocker');
const status = d.health.computed_status;
const atRisk = status === 'at_risk' || status === 'high_risk';
const escalate = d.health.escalation_candidate === true || securityConcern;

// ---------- Rules ----------
const holds = [];
if (degraded)       { holds.push('AI analysis failed'); hit('BR1_DEGRADED', 'AI classification or agent failed'); }
if (lowConfidence)  { holds.push('Low confidence');     hit('BR2_LOW_CONFIDENCE', `Confidence ${confidence} is below ${MIN_CONFIDENCE}`); }
if (knowledgeGap)   { holds.push('Knowledge gap');      hit('BR3_KNOWLEDGE_GAP', 'Knowledge needed but not sufficient'); }
if (securityConcern) hit('BR4_SECURITY', 'Security or data concern mentioned');
if (d.health.escalation_candidate) hit('BR5_ESCALATION_CANDIDATE', d.health.escalation_reasons.join('; '));
if (atRisk && !escalate) hit('BR6_AT_RISK', `Computed health is ${status}`);
if (isBilling)      hit('BR7_BILLING', 'Billing/administrative request goes to the Billing Team');
if (commercial)     hit('BR8_COMMERCIAL', 'Commercial signal detected');
if (blocker)        hit('BR9_ADOPTION_BLOCKER', 'Adoption blocker detected');

// ---------- Route ----------
let route = 'standard';
if (escalate) route = 'escalate';
else if (atRisk) route = 'csm_review';
else if (isBilling) route = 'billing';
else if (holds.length) route = 'human_review';
else if (commercial) route = 'commercial';
else if (blocker) route = 'adoption';

// ---------- Response mode ----------
// none = no AI draft, a human replies | template = fixed billing acknowledgment
// approval = draft then human approves | auto = draft can proceed
let responseMode;
if (holds.length) responseMode = 'none';
else if (isBilling) responseMode = 'template';
else if (route === 'escalate' || route === 'csm_review') responseMode = 'approval';
else responseMode = confidence >= AUTO_CONFIDENCE ? 'auto' : 'approval';

const humanReview = responseMode === 'approval' || responseMode === 'none'
  || ['escalate', 'csm_review', 'human_review'].includes(route);

// ---------- Notifications ----------
const notify = new Set();
if (escalate) { notify.add('csm'); notify.add('account_owner'); }
if (atRisk) notify.add('csm');
if (isBilling) notify.add('billing_team');
if (commercial) notify.add('account_owner');
if (blocker) notify.add('csm');

// ---------- Tasks ----------
const tasks = [];
const addTask = (task_type, assigned_to, due_in_days, label) =>
  tasks.push({ task_type, assigned_to, due_in_days, description: `${label}: ${d.ai.summary}` });
if (escalate || atRisk) addTask('risk_review', c.account_owner, 3, 'Risk review');
if (isBilling)          addTask('billing_handoff', 'Billing Team', 2, 'Billing handoff');
if (commercial)         addTask('commercial_followup', c.account_owner, 2, 'Commercial follow-up');
if (blocker)            addTask('adoption_check_in', c.account_owner, 5, 'Adoption check-in');

// ---------- Escalation ----------
const escalation = escalate ? {
  severity: securityConcern ? 'critical'
    : (status === 'high_risk' || d.health.signals.cancel_language) ? 'high' : 'medium',
  reason: [...d.health.escalation_reasons, ...(securityConcern ? ['Security or data concern'] : [])].join('; '),
  escalated_to: 'CS Manager'
} : null;

return {
  json: {
    ...d,
    routing: {
      route,
      response_mode: responseMode,
      human_review_required: humanReview,
      hold_reasons: holds,
      confidence_used: confidence,
      notify: [...notify],
      tasks,
      escalation,
      rules_triggered: rules,
      reasons
    }
  }
};

const base = $('Apply Business Rules').item.json;
const providedIds = base.knowledge.docs.map(d => d.doc_id);
const raw = String($json.text ?? '').replace(/```json|```/g, '').trim();

const BLOCKED_WORDS = /\b(refund|credit|discount|waive[ds]?|free of charge|guarantee[ds]?|promise[ds]?|pricing|price)\b/i;
const MONEY = /[$₱€£]\s?\d/;
const INTERNAL = /\b(health status|at[- ]risk|high[- ]risk|adoption score|churn|escalat\w*)\b/i;

let draft;
try {
  const p = JSON.parse(raw);
  if (typeof p.subject !== 'string' || typeof p.body !== 'string') throw new Error('missing subject/body');
  const body = p.body.trim();
  if (body.length < 20 || body.length > 1500) throw new Error('body length out of range');

  const used = Array.isArray(p.used_doc_ids) ? p.used_doc_ids.filter(id => providedIds.includes(id)) : [];
  const violations = [];
  if (BLOCKED_WORDS.test(body) || MONEY.test(body)) violations.push('financial or commitment wording');
  if (INTERNAL.test(body)) violations.push('internal terminology');
  if (base.ai.needs_knowledge_retrieval && used.length === 0) violations.push('no knowledge document cited');
  const fullySupported = p.fully_supported === true;

  draft = {
    status: fullySupported && violations.length === 0 ? 'ready' : 'needs_review',
    source: 'ai',
    subject: p.subject.trim().slice(0, 150),
    body,
    used_doc_ids: used,
    fully_supported: fullySupported,
    violations,
    error: null
  };
} catch (e) {
  draft = { status: 'failed', source: 'ai', subject: null, body: null,
            used_doc_ids: [], fully_supported: false, violations: [], error: e.message };
}

const routing = { ...base.routing };
if (draft.status === 'needs_review') {
  routing.response_mode = 'approval';
  routing.human_review_required = true;
  routing.hold_reasons = [...routing.hold_reasons, 'Draft needs review'];
}
if (draft.status === 'failed') {
  routing.response_mode = 'none';
  routing.human_review_required = true;
  routing.hold_reasons = [...routing.hold_reasons, 'Draft generation failed'];
}

return { json: { ...base, draft, routing } };

const d = $json;
const name = d.customer.contact_name || 'there';
const subject = d.message.subject ? `Re: ${d.message.subject}` : 'Your billing request';

const body = `Hi ${name},

Thank you for contacting us about your billing question. We have passed your request to our Billing Team, who will review it and respond within 2 business days.

If you have any additional details to share, such as an invoice number, you can reply to this email.

Best regards,
LearnLoop Customer Success Team`;

return {
  json: {
    ...d,
    draft: { status: 'ready', source: 'template', subject, body,
             used_doc_ids: [], fully_supported: true, violations: [], error: null }
  }
};

const d = $json;
const holds = d.routing.hold_reasons.length
  ? d.routing.hold_reasons
  : ['No retrieved knowledge to ground a response'];

return {
  json: {
    ...d,
    draft: { status: 'none', source: 'none', subject: null, body: null,
             used_doc_ids: [], fully_supported: false, violations: [], error: null },
    routing: { ...d.routing, response_mode: 'none', human_review_required: true, hold_reasons: holds }
  }
};

const CHANNELS = {
  csm: 'YOUR_CSM_SLACK_CHANNEL_ID',
  account_owner: 'YOUR_ACCOUNT_OWNER_SLACK_CHANNEL_ID',
  billing_team: 'YOUR_BILLING_SLACK_CHANNEL_ID',
  review: 'YOUR_REVIEW_SLACK_CHANNEL_ID'
};

const d = $json;
const c = d.customer;
const r = d.routing;

const LABELS = {
  escalate: ':rotating_light: Escalation',
  csm_review: ':warning: At-risk customer',
  billing: ':receipt: Billing request',
  human_review: ':raising_hand: Needs human review',
  commercial: ':chart_with_upwards_trend: Commercial opportunity',
  adoption: ':seedling: Adoption blocker',
  standard: ':speech_balloon: Customer message'
};

// ---------- Alert text ----------
const lines = [
  `*${LABELS[r.route]}: ${c.company_name}*`,
  `Contact: ${c.contact_name} (${c.customer_segment}, ${c.plan} plan) | Owner: ${c.account_owner}`,
  `Health: ${d.health.previous_status} → ${d.health.computed_status} | Adoption score: ${c.adoption_score}`,
  `Type: ${d.ai.request_type} | Sentiment: ${d.ai.sentiment}`,
  `Summary: ${d.ai.summary}`,
  `Rules: ${r.rules_triggered.join(', ') || 'none'}`
];
if (r.escalation) lines.push(`Escalation severity: ${r.escalation.severity}`);
if (r.tasks.length) lines.push(`Planned tasks: ${r.tasks.map(t => `${t.task_type} → ${t.assigned_to}`).join('; ')}`);
const alertText = lines.join('\n');

const alerts = r.notify.map(t => ({ target: t, channel: CHANNELS[t], text: alertText }));

// No AI draft: a human must write the reply
if (r.response_mode === 'none') {
  alerts.push({
    target: 'review',
    channel: CHANNELS.review,
    text: `${alertText}\n:no_entry: *No AI draft. Manual reply required.* Reasons: ${r.hold_reasons.join('; ')}`
  });
}

// ---------- Approval ----------
const needsApproval = r.response_mode === 'approval' && d.draft.body !== null;
const usedTitles = d.knowledge.docs
  .filter(x => d.draft.used_doc_ids.includes(x.doc_id))
  .map(x => x.title);

const approvalText = [
  `*Approval needed: reply to ${c.company_name}*`,
  `Route: ${r.route} | Confidence: ${r.confidence_used} | Draft status: ${d.draft.status}`,
  `Why review: ${r.hold_reasons.join('; ') || r.rules_triggered.join(', ') || 'approval mode'}`,
  `Knowledge used: ${usedTitles.join(', ') || 'none'}`,
  d.draft.violations.length ? `:warning: Draft flags: ${d.draft.violations.join('; ')}` : null,
  '',
  `*Subject:* ${d.draft.subject}`,
  d.draft.body
].filter(x => x !== null).join('\n');

return {
  json: {
    ...d,
    slack: { alerts, needs_approval: needsApproval, approval_text: approvalText, review_channel: CHANNELS.review }
  }
};

const base = $('Prepare Slack').item.json;
const mode = base.routing.response_mode;

let decision;
if (!base.slack.needs_approval) decision = 'not_required';
else if ($json.data && $json.data.approved === true) decision = 'approved';
else if ($json.data && $json.data.approved === false) decision = 'rejected';
else if ($json.error) decision = 'approval_failed';
else decision = 'timeout';

let sendEmail = false;
if (['auto', 'template'].includes(mode) && base.draft.status === 'ready') sendEmail = true;
if (mode === 'approval' && decision === 'approved') sendEmail = true;

return {
  json: {
    ...base,
    final: { decision, send_email: sendEmail, manual_reply_required: !sendEmail }
  }
};

const TEST_RECIPIENT = 'YOUR_TEST_EMAIL@example.com'; // test mode. Set to '' in production.

const d = $json;
const r = d.routing;
const c = d.customer;
const willEmail = d.final.send_email === true;

let status;
if (r.route === 'escalate') status = 'escalated';
else if (!willEmail) status = 'awaiting_review';
else if (r.route === 'standard') status = 'resolved';
else status = 'open';

const payload = {
  customer_id: c.customer_id,
  message_id: d.message.message_id,
  channel: d.message.channel,
  sender_email: d.message.sender_email,
  subject: d.message.subject,
  message_body: d.message.message_body,
  request_type: d.ai.request_type,
  sentiment: d.ai.sentiment,
  summary: d.ai.summary,
  topic_key: d.ai.topic_key,
  confidence: r.confidence_used,
  status,
  tasks: r.tasks,
  escalation: r.escalation,
  health_changed: d.health.status_changed,
  health_status: d.health.computed_status,
  adoption_score: c.adoption_score,
  risk_reason: d.health.reasons.join('; ') || null
};

return {
  json: {
    ...d,
    save: { payload_b64: Buffer.from(JSON.stringify(payload)).toString('base64'), status },
    email: { to: TEST_RECIPIENT || d.message.sender_email, send: willEmail }
  }
};

const base = $('Prepare Save').item.json;
return {
  json: {
    ...base,
    saved: {
      interaction_id: $json.interaction_id,
      duplicate: $json.duplicate,
      tasks_created: $json.tasks_created,
      escalations_created: $json.escalations_created,
      health_records_created: $json.health_records_created
    }
  }
};

