const emb = $input.first().json.embedding?.values;
if (!Array.isArray(emb) || emb.length === 0) return [];  // embedding failed: skip detection (case already saved)

const base = $('Merge Save Result').first().json;
const payload = { id: base.saved.interaction_id, emb };

return [{ json: { cluster_b64: Buffer.from(JSON.stringify(payload)).toString('base64') } }];

const CSM_CHANNEL = 'YOUR_CSM_SLACK_CHANNEL_ID';
const THRESHOLD = 3;

const r = $input.first().json;
const base = $('Merge Save Result').first().json;
const occ = r.occurrences;

// Alert at 3, then at every multiple of 5
if (occ < THRESHOLD || !(occ === THRESHOLD || occ % 5 === 0)) return [];

const top = base.knowledge.docs[0];
const recs = [];
if (base.ai.request_type === 'Technical Support') {
  recs.push('Review with Product/Support: a repeated technical issue may be a bug or a confusing workflow.');
} else if (!top) {
  recs.push('Create a knowledge article: no existing document matches this question.');
} else {
  recs.push(`Improve self-service: "${top.title}" already covers this, but customers keep asking. Add a clearer FAQ entry or in-app help link.`);
}
if (occ >= 5 && top) recs.push('Create a reusable response template for the support team.');

const text = [
  `:repeat: *Recurring question detected* (${occ} times in 30 days, ${r.customers} customer(s))`,
  `Example: ${r.example_summary}`,
  'Recommended:',
  ...recs.map(x => `• ${x}`)
].join('\n');

return [{ json: { channel: CSM_CHANNEL, text } }];

const REVIEW_CHANNEL = 'YOUR_REVIEW_SLACK_CHANNEL_ID';
const m = $('Validate Input').first().json.message;
return { json: {
  entry_b64: Buffer.from(JSON.stringify(m)).toString('base64'),
  channel: REVIEW_CHANNEL,
  text: `:grey_question: *Message from unknown sender* (${m.sender_email})\nSubject: ${m.subject}\nNo customer record matches this email. Not auto-replied. Needs manual review.`
} };

const REVIEW_CHANNEL = 'C_REPLACE_CS_REVIEW';
const d = $input.first().json;

// 'none' mode was already announced in Stage 11; alert only for failed approvals
if (!['rejected', 'timeout', 'approval_failed'].includes(d.final.decision)) return [];

const why = {
  rejected: 'Draft was rejected',
  timeout: 'Approval timed out',
  approval_failed: 'Approval request could not be sent'
}[d.final.decision];

return [{ json: {
  channel: REVIEW_CHANNEL,
  text: `:email: *Manual reply required: ${d.customer.company_name}*\n${why}. No email was sent.\nSubject: ${d.message.subject}\nSummary: ${d.ai.summary}`
} }];

const d = $json;
const problems = [];
if (d.ai_failed) problems.push('classification: ' + d.ai_error);
if (d.agent_failed) problems.push('agent: ' + d.agent_error);
if (d.knowledge.status === 'failed') problems.push('rag: failed');
if (d.draft.status === 'failed') problems.push('draft: ' + d.draft.error);

return { json: { entry: {
  customer_id: d.customer.customer_id,
  interaction_id: d.saved.interaction_id,
  event: 'case_processed',
  classification: d.ai.request_type,
  retrieved_doc_ids: d.knowledge.doc_ids,
  decision: `${d.routing.route} | ${d.routing.response_mode} | approval: ${d.final.decision}`,
  rule_triggered: d.routing.rules_triggered.join(','),
  ai_confidence: d.routing.confidence_used,
  human_involved: d.routing.human_review_required,
  action_taken: `tasks:${d.saved.tasks_created} escalations:${d.saved.escalations_created} email_planned:${d.email.send}`,
  success: problems.length === 0,
  error_message: problems.join('; ') || null
} } };

